# Put the person on hold, or take them off it when held. The audit line is written once it is saved,
# then the rollup lines: holding takes the person's OPEN claims out of every live total, releasing
# puts them back. No such person (404) writes nothing.
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonHold
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Puts the person on hold, or takes them off hold when they are held. */
public class HoldPerson {
    public void hold(@Val Person person, PersonRepository repository) {
        person.setHeld(!person.isHeld());
        repository.saveHeld(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the person put on hold, or taken off it, once it is saved. */
public class AuditPersonHold {
    public void audit(@Val Person person, @RequestParam(value = "user", required = false) String user, Audit audit) {
        audit.record((person.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + person.getSheetId()
                + " by=" + user + " name=" + person.getName());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
